// Create a new proxy factory and ensure non-null as the API implies successful construction is required for use.
pxProxyFactory *factory = px_proxy_factory_new();
if (!factory) { FUZZ_BAIL(); }
// Track lifetime to prevent double-free and use-after-free in subsequent stubs.
FUZZ_SET_ATTR_INT(factory, "freed", 0);
// Validation: factory is non-null and marked as not freed; ownership is returned to the fuzzer runtime as output.

// Pure function; retrieve the GType for pxProxyFactory. No inputs/outputs in pool.
// We stash it globally to aid potential cross-stub assertions without requiring a pointer-typed output.
GType t = px_proxy_factory_get_type();
// Record the type value (cast to int for attribute storage). Zero/non-zero is not specified by API, so we do not assert.
FUZZ_SET_ATTR_INT_GLOBAL("px_proxy_factory_gtype", (int)(unsigned long)t);
// Validation: Function invoked with no side effects; value stored globally for reference.

// Enforce that the factory is still alive.
if (FUZZ_GET_ATTR_INT(factory, "freed")) { FUZZ_BAIL(); }

// Build a plausible URL string: scheme://host[/path]
// Choose a scheme from common options, including socks variants to exercise code paths.
unsigned int r = *FUZZ_PARAM(unsigned int);
const char *schemes[] = {"http", "https", "ftp", "socks", "socks5", "socks4"};
const char *scheme = schemes[r % (sizeof(schemes)/sizeof(schemes[0]))];

// Generate host and path components from fuzz strings, filtering to a safe URL character set.
std::string host_raw = FUZZ_PARAM_STR();
std::string path_raw = FUZZ_PARAM_STR();
std::string host; host.reserve(64);
for (char c : host_raw) { if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '.' || c == '-' ) host.push_back(c); if (host.size() >= 63) break; }
if (host.empty()) host = "example.com";
std::string path; path.reserve(128);
for (char c : path_raw) { if ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z') || (c >= '0' && c <= '9') || c == '/' || c == '-' || c == '_' || c == '.' ) path.push_back(c); if (path.size() >= 127) break; }
if (!path.empty() && path[0] != '/') path.insert(path.begin(), '/');

std::string url = std::string(scheme) + "://" + host + path;
if (url.size() > 1024) { url.resize(1024); }

// Call the target function.
char **list = px_proxy_factory_get_proxies(factory, url.c_str());
// Per API, NULL indicates an unrecoverable error. To keep outputs non-null for the pool, bail on NULL here.
if (!list) { FUZZ_BAIL(); }

// Track provenance and lifetime on the returned proxies array so only the correct free function will consume it.
void *proxies = (void*)list;
FUZZ_SET_ATTR_STR(proxies, "origin", "px_proxy_factory_get_proxies");
FUZZ_SET_ATTR_INT(proxies, "freed", 0);
// Also record which scheme we asked for to diversify downstream logic (e.g., SOCKS handling in clients).
FUZZ_SET_ATTR_STR(proxies, "requested_scheme", scheme);

// Return the still-alive factory and the proxies array to the object pool.
// Validation: factory is preserved; proxies is non-null, attributed with origin, and not yet freed.

// Ensure this proxies pointer came from px_proxy_factory_get_proxies and hasn't been freed yet.
const char *origin = FUZZ_GET_ATTR_STR(proxies, "origin");
if (!origin || origin[0] == '\0') { FUZZ_BAIL(); }
int correct_origin = (std::string(origin) == "px_proxy_factory_get_proxies");
if (!correct_origin) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(proxies, "freed")) { FUZZ_BAIL(); }

// Free using the API and mark as freed. Do not access after freeing and do not return it as an output.
px_proxy_factory_free_proxies((char**)proxies);
FUZZ_SET_ATTR_INT(proxies, "freed", 1);
// Validation: Freed exactly once a proxies array allocated by the correct API; no objects returned to the pool.

// Enforce single free and that the factory was created by px_proxy_factory_new.
if (FUZZ_GET_ATTR_INT(factory, "freed")) { FUZZ_BAIL(); }

// The API requires no concurrent use; we cannot detect concurrency here, but we ensure we don't keep it in the pool.
px_proxy_factory_free(factory);
FUZZ_SET_ATTR_INT(factory, "freed", 1);
// Validation: Factory freed exactly once and dropped from the pool to avoid use-after-free.
